"""Render an operator-only HTML evidence snapshot from server.py report JSON."""
import collections, html, json, sys
from pathlib import Path
r=json.loads(Path(sys.argv[1]).read_text());out=Path(sys.argv[2])
e=lambda x:html.escape(str(x))
totals=collections.Counter()
for row in r['counts']:totals[row['event']]+=row['total'];totals['selected_files']+=row['files']
active={x['code'] for x in r['pilotActivity'] if x['event']=='tool_open' and x['tool'] not in {'pilot','home','privacy','install'}}
solved={x['code'] for x in r['pilotFeedback'] if x['solved']=='yes'}
def table(rows,keys):return '<table><tr>'+''.join('<th>'+e(k)+'</th>' for k in keys)+'</tr>'+''.join('<tr>'+''.join('<td>'+e(row.get(k,''))+'</td>' for k in keys)+'</tr>' for row in rows)+'</table>'
cards=[('Daily sessions (not people)',sum(x['sessions'] for x in r['dailySessions'])),('Locally selected files',totals['selected_files']),('Completed jobs',totals['job_completed']),('Download requests',totals['download_requested']),('Active pilot codes',len(active)),('Codes reporting a solved task',len(solved))]
body='<h1>UniLab usage evidence</h1><p>Generated '+e(r['generatedAt'])+' · 30-day window · operator snapshot</p><div class="cards">'+''.join('<div><b>'+e(v)+'</b><span>'+e(k)+'</span></div>' for k,v in cards)+'</div><p><strong>Goal: 30 distinct people completing useful tasks.</strong> Invitation codes are not automatically verified humans. Reconcile each code against the organiser’s separate participant checklist. Repeated sessions, downloads and automated tests must never be presented as distinct users.</p><h2>Pilot outcomes</h2>'+table(r['pilotSummary'],['code','completedJobs','downloadRequests'])+table(r['pilotFeedback'],['code','day','tool','solved','rating'])+'<h2>Usage by tool</h2>'+table(r['counts'],['day','tool','event','platform','version','total','files'])+'<h2>Measurement limits</h2><ul>'+''.join('<li>'+e(v)+'</li>' for v in r['definitions'].values())+'</ul><p>Selected files means local file input, never uploads to UniLab. Download requests can be canceled. Opt-out, offline use, blockers and failed requests are absent. Counts are observable activity, not a fraud-proof census.</p>'
out.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>UniLab usage evidence</title><style>body{font:16px/1.6 system-ui;color:#183430;max-width:1150px;margin:40px auto;padding:20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cards div{padding:20px;background:#e8f1ec;border-radius:12px}.cards b{display:block;font-size:38px}.cards span{display:block}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{padding:8px;border-bottom:1px solid #ccc;text-align:left;font-size:13px}@media(max-width:650px){.cards{grid-template-columns:1fr 1fr}}@media print{body{margin:0}tr{break-inside:avoid}}</style>'+body+'</html>')
